[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Fresh Pantry — Discover Everyday Deliciousness</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&family=Inter:wght@400;500;600&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --green-900: #1B4332;
      --green-800: #2D6A4F;
      --green-700: #40916C;
      --green-600: #52B788;
      --green-500: #74C69D;
      --green-100: #D8F3DC;
      --green-50: #F0FFF4;
      --orange-500: #F4A261;
      --orange-600: #E76F51;
      --yellow-400: #FBBF24;
      --cream: #FEFAE0;
      --cream-dark: #F5EDCC;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -1px rgba(0,0,0,0.04);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -2px rgba(0,0,0,0.04);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 10px 10px -5px rgba(0,0,0,0.03);
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', system-ui, sans-serif;
      color: var(--gray-800);
      background: var(--cream);
      line-height: 1.6;
      overflow-x: hidden;
    }

    h1, h2, h3, h4, h5, h6 {
      font-family: 'Nunito', 'Inter', sans-serif;
      line-height: 1.2;
    }

    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; border: none; font-family: inherit; }
    input { font-family: inherit; }

    /* ===== HEADER ===== */
    .site-header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(254, 250, 224, 0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.1);
      transition: box-shadow 0.3s ease;
    }
    .site-header.scrolled {
      box-shadow: var(--shadow-md);
    }
    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }
    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: 1.5rem;
      color: var(--green-800);
    }
    .logo-icon {
      width: 40px;
      height: 40px;
      background: var(--green-800);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-size: 1.25rem;
    }
    .nav-links {
      display: flex;
      gap: 32px;
      list-style: none;
    }
    .nav-links a {
      font-weight: 600;
      font-size: 0.95rem;
      color: var(--gray-700);
      transition: color 0.2s ease;
      position: relative;
    }
    .nav-links a::after {
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 2px;
      background: var(--green-700);
      border-radius: 1px;
      transition: width 0.3s ease;
    }
    .nav-links a:hover { color: var(--green-800); }
    .nav-links a:hover::after { width: 100%; }
    .mobile-menu-btn {
      display: none;
      background: none;
      font-size: 1.5rem;
      color: var(--green-800);
      padding: 4px;
    }
    .mobile-nav {
      display: none;
      background: var(--cream);
      border-bottom: 1px solid rgba(45, 106, 79, 0.15);
      padding: 16px 24px;
    }
    .mobile-nav.active { display: block; }
    .mobile-nav a {
      display: block;
      padding: 12px 0;
      font-weight: 600;
      color: var(--gray-700);
      border-bottom: 1px solid rgba(45, 106, 79, 0.08);
    }
    .mobile-nav a:last-child { border-bottom: none; }

    /* ===== HERO ===== */
    .hero {
      position: relative;
      overflow: hidden;
      background: linear-gradient(135deg, var(--green-800) 0%, var(--green-700) 50%, var(--green-600) 100%);
      padding: 100px 24px 110px;
      text-align: center;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(244, 162, 97, 0.15) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(116, 198, 157, 0.2) 0%, transparent 70%);
      border-radius: 50%;
    }
    .hero-content {
      position: relative;
      z-index: 2;
      max-width: 720px;
      margin: 0 auto;
    }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(8px);
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: var(--radius-full);
      padding: 8px 20px;
      font-size: 0.85rem;
      font-weight: 600;
      color: rgba(255,255,255,0.9);
      margin-bottom: 24px;
    }
    .hero-badge .dot {
      width: 8px;
      height: 8px;
      background: var(--yellow-400);
      border-radius: 50%;
      animation: pulse-dot 2s ease-in-out infinite;
    }
    @keyframes pulse-dot {
      0%, 100% { opacity: 1; transform: scale(1); }
      50% { opacity: 0.6; transform: scale(1.3); }
    }
    .hero h1 {
      font-size: clamp(2.2rem, 5vw, 3.5rem);
      font-weight: 900;
      color: white;
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }
    .hero p {
      font-size: clamp(1rem, 2vw, 1.2rem);
      color: rgba(255,255,255,0.85);
      margin-bottom: 36px;
      line-height: 1.7;
    }
    .hero-ctas {
      display: flex;
      gap: 16px;
      justify-content: center;
      flex-wrap: wrap;
    }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 14px 32px;
      border-radius: var(--radius-full);
      font-weight: 700;
      font-size: 0.95rem;
      transition: all 0.25s ease;
      white-space: nowrap;
    }
    .btn-primary {
      background: var(--orange-500);
      color: white;
      box-shadow: 0 4px 14px rgba(244, 162, 97, 0.35);
    }
    .btn-primary:hover {
      background: var(--orange-600);
      transform: translateY(-2px);
      box-shadow: 0 6px 20px rgba(244, 162, 97, 0.45);
    }
    .btn-outline {
      background: rgba(255,255,255,0.12);
      color: white;
      border: 2px solid rgba(255,255,255,0.35);
    }
    .btn-outline:hover {
      background: rgba(255,255,255,0.22);
      border-color: rgba(255,255,255,0.5);
      transform: translateY(-2px);
    }

    /* ===== SECTION SHARED ===== */
    .section {
      padding: 80px 24px;
    }
    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }
    .section-header h2 {
      font-size: clamp(1.75rem, 3vw, 2.25rem);
      font-weight: 800;
      color: var(--green-800);
      margin-bottom: 12px;
    }
    .section-header p {
      font-size: 1.05rem;
      color: var(--gray-500);
      max-width: 540px;
      margin: 0 auto;
    }
    .section-label {
      display: inline-block;
      font-size: 0.8rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--green-700);
      background: var(--green-100);
      padding: 6px 16px;
      border-radius: var(--radius-full);
      margin-bottom: 12px;
    }

    /* ===== FEATURED PRODUCTS CAROUSEL ===== */
    .featured-section {
      background: var(--white);
    }
    .carousel-wrapper {
      position: relative;
    }
    .carousel-track {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding: 8px 4px 20px;
      scrollbar-width: none;
      -ms-overflow-style: none;
    }
    .carousel-track::-webkit-scrollbar { display: none; }
    .product-card {
      flex: 0 0 260px;
      background: var(--gray-50);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: transform 0.3s ease, box-shadow 0.3s ease;
      border: 1px solid var(--gray-100);
    }
    .product-card:hover {
      transform: translateY(-6px);
      box-shadow: var(--shadow-xl);
      border-color: var(--green-200, #bbf7d0);
    }
    .product-img {
      height: 180px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3.5rem;
      position: relative;
      overflow: hidden;
    }
    .product-img-1 { background: linear-gradient(135deg, #FEF3C7, #FDE68A); }
    .product-img-2 { background: linear-gradient(135deg, #F3F4F6, #E5E7EB); }
    .product-img-3 { background: linear-gradient(135deg, #FCE7F3, #FBCFE8); }
    .product-img-4 { background: linear-gradient(135deg, #ECFDF5, #D1FAE5); }
    .product-img-5 { background: linear-gradient(135deg, #FEF3C7, #FBBF24); }
    .product-img-6 { background: linear-gradient(135deg, #FFF7ED, #FED7AA); }
    .product-img-7 { background: linear-gradient(135deg, #FEF9C3, #FDE047); }
    .product-img-8 { background: linear-gradient(135deg, #F5F3FF, #DDD6FE); }
    .product-info {
      padding: 18px 20px 22px;
    }
    .product-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      color: var(--gray-800);
      margin-bottom: 6px;
    }
    .product-desc {
      font-size: 0.85rem;
      color: var(--gray-500);
      line-height: 1.5;
      margin-bottom: 12px;
    }
    .product-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.15rem;
      color: var(--green-800);
    }
    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: white;
      border: 1px solid var(--gray-200);
      box-shadow: var(--shadow-lg);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.25rem;
      color: var(--green-800);
      transition: all 0.2s ease;
      z-index: 5;
    }
    .carousel-btn:hover {
      background: var(--green-800);
      color: white;
      border-color: var(--green-800);
    }
    .carousel-btn-left { left: -8px; }
    .carousel-btn-right { right: -8px; }

    /* ===== SEASONAL PICKS ===== */
    .seasonal-section {
      background: linear-gradient(180deg, var(--cream) 0%, var(--white) 100%);
    }
    .seasonal-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
      gap: 24px;
    }
    .seasonal-card {
      background: white;
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--gray-100);
      transition: transform 0.3s ease, box-shadow 0.3s ease;
    }
    .seasonal-card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }
    .seasonal-img {
      height: 160px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
    }
    .seasonal-img-1 { background: linear-gradient(135deg, #ECFDF5, #A7F3D0); }
    .seasonal-img-2 { background: linear-gradient(135deg, #FEF3C7, #FBBF24); }
    .seasonal-img-3 { background: linear-gradient(135deg, #F5F3FF, #C4B5FD); }
    .seasonal-img-4 { background: linear-gradient(135deg, #FFF7ED, #FDBA74); }
    .seasonal-info {
      padding: 20px;
    }
    .seasonal-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--gray-800);
      margin-bottom: 6px;
    }
    .seasonal-desc {
      font-size: 0.88rem;
      color: var(--gray-500);
      line-height: 1.5;
      margin-bottom: 10px;
    }
    .seasonal-price {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.1rem;
      color: var(--orange-600);
    }
    .seasonal-tag {
      display: inline-block;
      background: linear-gradient(135deg, #FBBF24, #F59E0B);
      color: white;
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      padding: 4px 10px;
      border-radius: var(--radius-full);
      margin-bottom: 10px;
    }

    /* ===== CATEGORIES ===== */
    .categories-section {
      background: var(--white);
    }
    .categories-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
      gap: 20px;
    }
    .category-card {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      height: 220px;
      cursor: pointer;
      transition: transform 0.35s ease;
    }
    .category-card:hover {
      transform: scale(1.04);
    }
    .category-bg {
      position: absolute;
      inset: 0;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 4rem;
      transition: filter 0.35s ease;
    }
    .category-card:hover .category-bg {
      filter: blur(2px) brightness(0.7);
    }
    .cat-bg-1 { background: linear-gradient(135deg, #FDE68A, #F59E0B); }
    .cat-bg-2 { background: linear-gradient(135deg, #A7F3D0, #34D399); }
    .cat-bg-3 { background: linear-gradient(135deg, #BAE6FD, #38BDF8); }
    .cat-bg-4 { background: linear-gradient(135deg, #FECACA, #F87171); }
    .cat-bg-5 { background: linear-gradient(135deg, #FED7AA, #FB923C); }
    .category-overlay {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      background: rgba(45, 106, 79, 0.0);
      transition: background 0.35s ease;
      padding: 20px;
    }
    .category-card:hover .category-overlay {
      background: rgba(45, 106, 79, 0.55);
    }
    .category-name-overlay {
      font-family: 'Nunito', sans-serif;
      font-weight: 800;
      font-size: 1.3rem;
      color: white;
      opacity: 0;
      transform: translateY(10px);
      transition: all 0.35s ease;
      text-shadow: 0 2px 8px rgba(0,0,0,0.2);
    }
    .category-card:hover .category-name-overlay {
      opacity: 1;
      transform: translateY(0);
    }
    .category-desc-overlay {
      font-size: 0.85rem;
      color: rgba(255,255,255,0.9);
      opacity: 0;
      transform: translateY(10px);
      transition: all 0.35s ease 0.05s;
      text-align: center;
      margin-top: 6px;
    }
    .category-card:hover .category-desc-overlay {
      opacity: 1;
      transform: translateY(0);
    }
    .category-name-static {
      position: absolute;
      bottom: 16px;
      left: 16px;
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      color: white;
      text-shadow: 0 2px 8px rgba(0,0,0,0.3);
      transition: opacity 0.3s ease;
    }
    .category-card:hover .category-name-static {
      opacity: 0;
    }

    /* ===== BRAND HIGHLIGHTS ===== */
    .highlights-section {
      background: linear-gradient(135deg, var(--green-800) 0%, var(--green-700) 100%);
      padding: 60px 24px;
    }
    .highlights-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .highlights-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }
    .highlight-item {
      text-align: center;
      padding: 24px 16px;
    }
    .highlight-number {
      font-family: 'Nunito', sans-serif;
      font-weight: 900;
      font-size: clamp(2rem, 4vw, 2.8rem);
      color: var(--orange-500);
      margin-bottom: 8px;
      line-height: 1;
    }
    .highlight-label {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1rem;
      color: white;
      margin-bottom: 6px;
    }
    .highlight-desc {
      font-size: 0.85rem;
      color: rgba(255,255,255,0.65);
      line-height: 1.5;
    }

    /* ===== STORE LOCATOR ===== */
    .store-section {
      background: var(--cream);
    }
    .store-search {
      display: flex;
      gap: 12px;
      max-width: 480px;
      margin: 0 auto 40px;
    }
    .store-input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-full);
      font-size: 0.95rem;
      background: white;
      color: var(--gray-800);
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
      outline: none;
    }
    .store-input:focus {
      border-color: var(--green-600);
      box-shadow: 0 0 0 3px rgba(82, 183, 136, 0.15);
    }
    .store-input::placeholder { color: var(--gray-400); }
    .store-search-btn {
      padding: 14px 28px;
      background: var(--green-800);
      color: white;
      border-radius: var(--radius-full);
      font-weight: 700;
      font-size: 0.95rem;
      transition: all 0.25s ease;
      white-space: nowrap;
    }
    .store-search-btn:hover {
      background: var(--green-900);
      transform: translateY(-1px);
    }
    .store-results {
      display: none;
      max-width: 800px;
      margin: 0 auto;
    }
    .store-results.active { display: block; }
    .store-results-header {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--green-800);
      margin-bottom: 16px;
    }
    .store-result-card {
      background: white;
      border-radius: var(--radius-md);
      padding: 24px;
      margin-bottom: 12px;
      border: 1px solid var(--gray-100);
      display: flex;
      align-items: center;
      gap: 20px;
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }
    .store-result-card:hover {
      transform: translateX(4px);
      box-shadow: var(--shadow-md);
    }
    .store-icon {
      width: 48px;
      height: 48px;
      background: var(--green-100);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.3rem;
      flex-shrink: 0;
    }
    .store-details { flex: 1; }
    .store-name {
      font-family: 'Nunito', sans-serif;
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--gray-800);
      margin-bottom: 4px;
    }
    .store-address {
      font-size: 0.88rem;
      color: var(--gray-500);
    }
    .store-meta {
      text-align: right;
      flex-shrink: 0;
    }
    .store-hours {
      font-size: 0.85rem;
      color: var(--green-700);
      font-weight: 600;
      margin-bottom: 4px;
    }
    .store-distance {
      font-size: 0.85rem;
      color: var(--gray-400);
    }

    /* ===== NEWSLETTER ===== */
    .newsletter-section {
      background: linear-gradient(135deg, var(--green-50) 0%, var(--green-100) 100%);
    }
    .newsletter-inner {
      max-width: 560px;
      margin: 0 auto;
      text-align: center;
    }
    .newsletter-icon {
      font-size: 2.5rem;
      margin-bottom: 16px;
    }
    .newsletter-form {
      display: flex;
      gap: 12px;
      max-width: 440px;
      margin: 0 auto;
    }
    .newsletter-input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-full);
      font-size: 0.95rem;
      background: white;
      color: var(--gray-800);
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
      outline: none;
    }
    .newsletter-input:focus {
      border-color: var(--green-600);
      box-shadow: 0 0 0 3px rgba(82, 183, 136, 0.15);
    }
    .newsletter-input::placeholder { color: var(--gray-400); }
    .newsletter-btn {
      padding: 14px 28px;
      background: var(--orange-500);
      color: white;
      border-radius: var(--radius-full);
      font-weight: 700;
      font-size: 0.95rem;
      transition: all 0.25s ease;
      white-space: nowrap;
    }
    .newsletter-btn:hover {
      background: var(--orange-600);
