  <script>
    // ===== HEADER SCROLL EFFECT =====
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    });

    // ===== MOBILE MENU =====
    const mobileMenuBtn = document.getElementById('mobileMenuBtn');
    const mobileNav = document.getElementById('mobileNav');
    mobileMenuBtn.addEventListener('click', () => {
      mobileNav.classList.toggle('active');
      mobileMenuBtn.textContent = mobileNav.classList.contains('active') ? '✕' : '☰';
    });
    mobileNav.querySelectorAll('a').forEach(a => {
      a.addEventListener('click', () => {
        mobileNav.classList.remove('active');
        mobileMenuBtn.textContent = '☰';
      });
    });

    // ===== PRODUCT CAROUSEL =====
    const carouselTrack = document.getElementById('carouselTrack');
    const leftBtn = document.getElementById('carouselLeft');
    const rightBtn = document.getElementById('carouselRight');
    const scrollAmount = 280;

    leftBtn.addEventListener('click', () => {
      carouselTrack.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
    });
    rightBtn.addEventListener('click', () => {
      carouselTrack.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    });

    // ===== STORE LOCATOR =====
    const storeInput = document.getElementById('storeInput');
    const storeSearchBtn = document.getElementById('storeSearchBtn');
    const storeResults = document.getElementById('storeResults');

    storeSearchBtn.addEventListener('click', () => {
      const zip = storeInput.value.trim();
      if (zip.length >= 5 && /^\d{5}$/.test(zip)) {
        storeResults.classList.add('active');
        storeResults.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      } else {
        storeInput.style.borderColor = '#EF4444';
        storeInput.style.boxShadow = '0 0 0 3px rgba(239, 68, 68, 0.15)';
        setTimeout(() => {
          storeInput.style.borderColor = '';
          storeInput.style.boxShadow = '';
        }, 2000);
      }
    });

    storeInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') storeSearchBtn.click();
    });

    // ===== NEWSLETTER SIGNUP =====
    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterInput = document.getElementById('newsletterInput');
    const newsletterBtn = document.getElementById('newsletterBtn');
    const newsletterConfirm = document.getElementById('newsletterConfirm');

    newsletterBtn.addEventListener('click', () => {
      const email = newsletterInput.value.trim();
      if (email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        newsletterConfirm.classList.add('active');
        newsletterForm.style.display = 'none';
      } else {
        newsletterInput.style.borderColor = '#EF4444';
        newsletterInput.style.boxShadow = '0 0 0 3px rgba(239, 68, 68, 0.15)';
        setTimeout(() => {
          newsletterInput.style.borderColor = '';
          newsletterInput.style.boxShadow = '';
        }, 2000);
      }
    });

    newsletterInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') newsletterBtn.click();
    });
  </script>
